def count_primes(n):
    """Number of primes p with 2 <= p < n. n is an int, may be 0 or negative."""
    if n <= 2:
        return 0
    size = n >> 1
    sieve = bytearray(b'\x01') * size
    sieve[0] = 0
    limit = (isqrt(n) - 1) >> 1
    # local bindings
    sv = sieve
    zero = b'\x00'
    for i in range(1, limit + 1):
        if sv[i]:
            p = (i << 1) + 1
            start = (p * p - 1) >> 1
            step = p
            sv[start::step] = zero * ((size - 1 - start) // step + 1)
    return 1 + sv.count(1)
